import requests

BASE_URL = "http://localhost:8000"
TOKEN = "eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"

def test_driver_get_wallet_balance():
    url = f"{BASE_URL}/api/v1/drivers/me/wallet"
    headers = {
        "Authorization": f"Bearer {TOKEN}"
    }
    try:
        response = requests.get(url, headers=headers, timeout=30)
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

    assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    # Adjusted expected keys based on typical wallet response from PRD description
    required_keys = [
        "cashback",
        "maintenance_savings",
        "currency"
    ]

    for key in required_keys:
        assert key in data, f"'{key}' field is missing from wallet data"

    # Validate types of some fields
    assert isinstance(data["cashback"], (int, float)), "'cashback' should be a number"
    assert isinstance(data["maintenance_savings"], (int, float)), "'maintenance_savings' should be a number"
    assert isinstance(data["currency"], str), "'currency' should be a string"

    # Optionally check 'balance' as sum or presence if applicable
    if "balance" in data:
        assert isinstance(data["balance"], (int, float)), "'balance' should be a number"

test_driver_get_wallet_balance()
